// Normas da CGJ (NSCGJ), Tomo I — arts. 132 a 189-G (intimações a arquivamento) e 1.189 a 1.301 (processo eletrônico).
// Complementa normas-tjsp.js (arts. 5º a 131).
window.CARDS = (window.CARDS || []).concat([
  { id: "ncgj2-1", lei: "Normas TJSP", ref: "NSCGJ, Tomo I, arts. 132 e 133",
    frente: "Intimação: meio, vedação de informações por telefone e prazo de encaminhamento à publicação (arts. 132 e 133).",
    verso: "Sempre que possível, por MEIO ELETRÔNICO e publicação no DJE. É VEDADO ao servidor dos ofícios de justiça prestar INFORMAÇÕES POR TELEFONE a advogados, MP, partes e público sobre atos e termos do processo. Despachos, decisões interlocutórias e sentenças vão à publicação no DJE em no MÁXIMO 3 DIAS da devolução dos autos em cartório (mesmo prazo para cumprir a intimação eletrônica)." },
  { id: "ncgj2-2", lei: "Normas TJSP", ref: "NSCGJ, Tomo I, arts. 134 a 138",
    frente: "Intimações: conteúdo, parte dispositiva, nulidade e segredo de justiça (arts. 134 a 138).",
    verso: "Conteúdo (art. 134): número dos autos, objeto (tabela vigente) e nome das partes; resumo ou transcrição suficiente; nome dos advogados com número da OAB. Art. 135: havendo mais de um advogado, consta o subscritor da inicial, contestação ou primeira intervenção (ou, a pedido, no máximo 2 nomes ou a sociedade de advogados); decisões INTERLOCUTÓRIAS e SENTENÇAS publicam-se SÓ na parte DISPOSITIVA; atos ordinatórios e despachos de mero expediente são transcritos ou resumidos; decisões disciplinares e de dúvida: só o dispositivo (Corregedor pode determinar publicação integral após o trânsito). Art. 136: publicação omissa que cause EFETIVO PREJUÍZO é NULA. Art. 137: erro ou omissão → retificação e nova publicação, de imediato, independentemente de despacho ou reclamação. Art. 138: segredo de justiça → INICIAIS das partes." },
  { id: "ncgj2-3", lei: "Normas TJSP", ref: "NSCGJ, Tomo I, arts. 139 a 142",
    frente: "Taxa e valores nas intimações, certidão da publicação e editais (arts. 139 a 142).",
    verso: "Art. 139: o escrivão publica, com as intimações, o valor da TAXA JUDICIÁRIA e das importâncias a depositar; intimações sobre cálculos e contas trazem os valores em resumo. Art. 140: a publicação no DJE documenta-se pelo encarte da CERTIDÃO gerada pelo sistema (ou aposta ao pé/verso da folha); comprova-se por certidão, sem juntar exemplar impresso. Art. 141 (EDITAL): folhas autenticadas com a chancela do ofício e rubricadas pelo escrivão; publicação no DJE, internet, site do tribunal ou plataforma de editais do CNJ comprova-se por certidão; jornal local providenciado pela PARTE ou agência de sua escolha; entrega da minuta sempre mediante RECIBO (pode ser a estagiário ou advogado com procuração). Em SEGREDO DE JUSTIÇA, o edital de citação traz o NOME COMPLETO do réu e só o conteúdo INDISPENSÁVEL, SEM as especificações da inicial, abreviando os nomes das demais partes. Art. 142: escrivães velam pelo cumprimento, conferindo DIARIAMENTE o teor." },
  { id: "ncgj2-4", lei: "Normas TJSP", ref: "NSCGJ, Tomo I, arts. 143 a 146",
    frente: "Audiências: designação, adiamento e termos de audiência (arts. 143 a 146).",
    verso: "Art. 143: a designação de audiências é atribuição EXCLUSIVA e INDELEGÁVEL do JUIZ, salvo nos juizados especiais. Art. 144: adiamento ou nova designação → nova data marcada NO PRÓPRIO TERMO, com ciência imediata aos comparecentes; acordos extrajudiciais, desistências e pedidos de suspensão podem ser homologados ou deferidos sem realizar a audiência já designada (aproveitando a data para outro ato). Art. 145: termos de audiência LAVRADOS SOB DITADO DO JUIZ, RUBRICADOS em todas as folhas pelo juiz, SUBSCRITOS por juiz, advogados, MP e escrevente (assinaturas identificadas com nomes ou cargos) e juntados em sua versão ORIGINAL. Art. 146: contêm em RESUMO o ocorrido, inclusive, por EXTENSO, os despachos e a sentença proferida no ato." },
  { id: "ncgj2-5", lei: "Normas TJSP", ref: "NSCGJ, Tomo I, arts. 147 a 149-A",
    frente: "Qualificação de depoentes, verificação prévia e gravação (arts. 147 a 149-A).",
    verso: "Art. 147: depoentes são qualificados com nome, filiação, nacionalidade, data e local de nascimento, estado civil, profissão, endereço residencial e profissional, RG ou outro documento. Art. 148: o servidor dos registros e audiências examina os processos 10 DIAS ANTES das audiências, verificando intimações e requisições; irregularidade → comunicação imediata. Art. 149: faculta-se aos juízos de 1º grau gravação magnética, estenotipia, digital ou audiovisual; a adoção é anotada no termo, com qualificações por escrito e repetidas verbalmente. Art. 149-A: a parte que exercer a faculdade do art. 367, §6º do CPC (gravar diretamente) COMUNICA o Magistrado PREVIAMENTE ao início; o juiz consigna no termo o nome da parte e o meio; para usar a gravação, a parte faz a INTEGRAL TRANSCRIÇÃO, com ciência à parte contrária (manifestação em 5 DIAS)." },
  { id: "ncgj2-6", lei: "Normas TJSP", ref: "NSCGJ, Tomo I, arts. 150 a 156",
    frente: "Gravação de audiências: sistema, transcrição, armazenamento e cópia (arts. 150 a 156).",
    verso: "Art. 150: gravadas DIRETAMENTE no sistema informatizado oficial e armazenadas em NUVEM. Art. 152: depoimentos em meio audiovisual NÃO são transcritos; a transcrição pelo ofício só ocorre se houver RECURSO E for IMPOSSÍVEL o envio da documentação eletrônica. Art. 153: após o trânsito em julgado, o registro permanece armazenado até o fim do prazo da AÇÃO RESCISÓRIA (processo civil) e após a EXTINÇÃO DA PENA (processo penal). Art. 154: a parte interessada recebe, se solicitar, cópia do termo (impresso logo após o ato) e do registro audiovisual. Art. 156: cabe à STI editar orientações técnicas sobre sistemas, forma de gravação e equipamentos." },
  { id: "ncgj2-7", lei: "Normas TJSP", ref: "NSCGJ, Tomo I, art. 156-A",
    frente: "Estações Passivas e oitiva por carta precatória (art. 156-A).",
    verso: "É VEDADA a expedição de carta precatória para oitivas, presenciais ou remotas, em outras comarcas do Estado de São Paulo (ressalvadas as exceções do art. 122, §3º). O DOMICÍLIO da pessoa a ser ouvida determina a ESTAÇÃO PASSIVA. A Unidade Judicial agenda diretamente na agenda eletrônica da Estação Passiva, certifica data e horário e promove as intimações por ato ordinatório. Nas hipóteses do art. 455, §4º do CPC, depreca-se a INTIMAÇÃO da pessoa. Solicitações de outros órgãos do Judiciário: por e-mail à Estação Passiva competente." },
  { id: "ncgj2-8", lei: "Normas TJSP", ref: "NSCGJ, Tomo I, arts. 157 a 160 · já caiu",
    frente: "Consulta aos autos: quem pode, forma e carga rápida para cópia (arts. 157 a 160).",
    verso: "Art. 157: o acesso a autos em andamento ou findos, MESMO SEM PROCURAÇÃO, quando NÃO sujeitos a segredo de justiça, é assegurado a advogados, estagiários de Direito e ao PÚBLICO EM GERAL, por exame em BALCÃO, podendo tomar apontamentos, pedir cópias e usar escâner portátil ou câmera — VEDADO o DESENCARTE de peças. Os escrivães/chefes de seção mantêm rigorosa vigilância. Art. 158: advogados ou estagiários inscritos na OAB que NÃO sejam procuradores das partes podem retirar os autos para cópia por 1 HORA (carga rápida), com consulta ao site da OAB; a pessoa credenciada deve apresentar a autorização (art. 272, §7º CPC) e documento de identidade. Art. 159: casos complexos ou com pluralidade de interesses: cópias de todo o feito ficam à disposição. Art. 160 (SEGREDO DE JUSTIÇA): exame em cartório restrito às PARTES e seus PROCURADORES constituídos; entidades de assistência judiciária podem autorizar acadêmicos de Direito não inscritos, por advogado com procuração; é VEDADO o acesso por estagiário não inscrito ou com inscrição vencida." },
  { id: "ncgj2-9", lei: "Normas TJSP", ref: "NSCGJ, Tomo I, art. 161 a 163 · já caiu",
    frente: "Carga de autos: quem pode retirar e credenciamento de prepostos (arts. 161 a 163).",
    verso: "Art. 161: a carga de autos em andamento é reservada UNICAMENTE a advogados ou estagiários inscritos na OAB, CONSTITUÍDOS PROCURADORES de alguma das partes; ressalva: nos processos FINDOS e SEM segredo de justiça, o advogado, MESMO SEM procuração, pode retirar por 10 DIAS. Pode ser feita por pessoa credenciada, Advocacia Pública, Defensoria ou MP (implica INTIMAÇÃO de qualquer decisão do processo, ainda que pendente de publicação). Art. 162: retirada e devolução registradas no sistema e no relatório de carga (assinatura na retirada, baixa na devolução, relatório juntado aos autos); o Livro Protocolo de Autos e Papéis só se o sistema não puder ser usado; consta o número da OAB e seção; a baixa é feita IMEDIATAMENTE, à vista do interessado. Art. 163: advogados, sociedades, Fazenda, MP e Defensoria indicam prepostos por PETIÇÃO ao JUIZ CORREGEDOR PERMANENTE (arquivada em pasta própria), com nomes, RG, CPF e identificação funcional; o preposto porta identidade e cédula/crachá; qualquer alteração do rol é comunicada imediatamente." },
  { id: "ncgj2-10", lei: "Normas TJSP", ref: "NSCGJ, Tomo I, arts. 164 a 166",
    frente: "Carga na fluência de prazo, carga rápida e retenção de documento (arts. 164 a 166).",
    verso: "Art. 164: sem fluência de prazo, a carga depende de REQUERIMENTO; NA FLUÊNCIA DE PRAZO os autos NÃO saem do ofício, salvo hipóteses legais, ressalvado o direito de cópias com justificada urgência e autorização judicial; em PRAZO COMUM só retiram EM CONJUNTO ou mediante AJUSTE por petição, ressalvada a obtenção de cópias, por 2 a 6 HORAS, mediante carga, independentemente de ajuste. Art. 165 (CARGA RÁPIDA): concedida pelo escrivão ou escrevente por 1 HORA, com formulário assinado por advogado ou estagiário constituído ou pessoa credenciada; requerimentos até 1 HORA antes do fim do expediente; formulário juntado aos autos na devolução; não restituídos no prazo, o escrivão representa em 24 HORAS ao Juiz Corregedor Permanente. Art. 166: é VEDADA a RETENÇÃO do documento de identificação do advogado ou estagiário para controle de carga, em qualquer circunstância." },
  { id: "ncgj2-11", lei: "Normas TJSP", ref: "NSCGJ, Tomo I, arts. 167 a 169 · já caiu",
    frente: "Não devolução de autos: perda do direito à vista e multa (arts. 167 a 169).",
    verso: "Art. 167: se, intimado PESSOALMENTE, o advogado não devolver os autos em 3 DIAS, PERDE o direito à vista fora de cartório e incorre em MULTA correspondente à METADE DO SALÁRIO MÍNIMO; o juiz comunica a seção local da OAB; o expediente de cobrança recebe autuação singela (sem registro); em EXTRAVIO, instrui a RESTAURAÇÃO. Art. 168: o escrivão ou chefe de seção verifica MENSALMENTE, até o 10º DIA ÚTIL do mês subsequente, os prazos de devolução e relaciona, em 2 VIAS, os autos em poder das partes além do prazo (uma ao Juiz Corregedor Permanente, outra arquivada). Art. 169: aplica-se a todos os demais destinatários de carga." },
  { id: "ncgj2-12", lei: "Normas TJSP", ref: "NSCGJ, Tomo I, arts. 170 a 175",
    frente: "Desentranhamento de peças e documentos (arts. 170 a 175).",
    verso: "Art. 170: pode ser requerido pelo interessado ou determinado de ofício pelo juiz, facultada a substituição por CÓPIA simples. Art. 171: NÃO há substituição por cópia, a critério do juiz, quando se referirem a: manifestação INTEMPESTIVA; documentação evidentemente ESTRANHA aos autos; documentos que NÃO serviram de base a decisão ou à manifestação da parte contrária — coloca-se FOLHA EM BRANCO, anota-se a folha da certidão, VEDADA a RENUMERAÇÃO. Peças juntadas por equívoco são desentranhadas imediatamente. Art. 172: certifica-se, guarda-se em local adequado e INTIMA-SE o interessado a retirar em 5 DIAS; guardadas em classificador próprio, VEDADO grampeá-las na contracapa; devolução mediante TERMO. Art. 173: dispensada a certificação do número do processo nas peças desentranhadas (salvo ordem judicial e TÍTULOS DE CRÉDITO). Art. 174: transitada em julgado a sentença, os OBJETOS são devolvidos mediante solicitação ou intimação para retirada em até 30 DIAS, sob pena de DESTRUIÇÃO. Art. 175: verificação periódica do classificador; decorridos 11 MESES da intimação, EDITAL para retirada em 30 DIAS, sob pena de inutilização, com cópia à OAB local; feito pelo menos UMA VEZ ao ano e constado na ata de correição." },
  { id: "ncgj2-13", lei: "Normas TJSP", ref: "NSCGJ, Tomo I, arts. 176 a 179",
    frente: "Arquivamento: condições, prazo no ofício e arquivo provisório (arts. 176 a 179).",
    verso: "Art. 176: NENHUM processo é arquivado sem SENTENÇA DEFINITIVA ou DECISÃO TERMINATIVA (inclusive extinção por estabilização da tutela, art. 304, §1º CPC), salvo suspensão por prazo indeterminado. Art. 177: após a publicação da decisão de arquivamento, o processo permanece no ofício por 30 DIAS; depois é arquivado após anotações no sistema oficial e no SGDAU. Art. 178: cumprimento de sentença em juízo diverso (art. 516, par. único CPC): o arquivamento é promovido pelo JUÍZO DA EXECUÇÃO. Art. 179: ARQUIVO PROVISÓRIO de processos em execução de título judicial há mais de 1 ANO sem localização de bens; mantido o nome das partes no Distribuidor; excluídos das estatísticas mensais." },
  { id: "ncgj2-14", lei: "Normas TJSP", ref: "NSCGJ, Tomo I, arts. 180 a 183",
    frente: "Arquivo terceirizado, desarquivamento e segredo de justiça (arts. 180 a 183).",
    verso: "Art. 180: VEDADA às partes e advogados a consulta ou retirada de processos nos depósitos do ARQUIVO TERCEIRIZADO. Art. 181: o interessado consulta o processo no OFÍCIO onde tramitou; a unidade requisita no SGDAU, após recolher a TAXA de desarquivamento (salvo gratuidade ou isenção); é intimado da chegada dos autos e do prazo de 30 DIAS para manifestação; sem manifestação, os autos retornam ao arquivo. Art. 182: é expressamente VEDADO o manuseio de autos em SEGREDO DE JUSTIÇA, exceto às PARTES e advogados por elas constituídos ou por ORDEM JUDICIAL expressa; cópia, certidão e desentranhamento dependem de DESPACHO do juiz. Art. 183: pesquisa histórica mediante solicitação prévia à Coordenadoria de Gestão Documental e Arquivos." },
  { id: "ncgj2-15", lei: "Normas TJSP", ref: "NSCGJ, Tomo I, arts. 184 a 187",
    frente: "Arquivamento e rearquivamento: cautelas e dados (arts. 184 a 187).",
    verso: "Art. 184: o primeiro arquivamento é INDIVIDUAL, dispensando caixas: indexar cada processo e volume no SGDAU; indicar o número do volume; afixar a ETIQUETA no canto superior ESQUERDO da capa; indicar o número de apensos; apenso com numeração autônoma é indexado informando a vinculação. No sistema oficial os dados devem estar anotados, com processo baixado (extinção) ou decisão terminativa. Art. 185: remessa conforme escala publicada no DJE. Art. 186 (rearquivamento): informa-se vara, números de registro, classe e assunto, partes (sem abreviações), advogados com OAB, objeto, data da decisão final, resultado, trânsito em julgado e extinção. Art. 187: dispensa caixas, pacotes e malotes, mas separados de forma distinta os novos arquivamentos e os rearquivamentos." },
  { id: "ncgj2-16", lei: "Normas TJSP", ref: "NSCGJ, Tomo I, arts. 188 e 189",
    frente: "Desarquivamento: taxa e requisição ao arquivo terceirizado (arts. 188 e 189).",
    verso: "Art. 188: requerimento instruído com o comprovante da TAXA (salvo exceções legais); sem a guia, o advogado é intimado a recolher em 5 DIAS, sob pena de não prosseguimento. Art. 189: o ofício requisita no SGDAU e anota no sistema oficial a data; em processo apenso, informa o PRINCIPAL; antes, verifica se foi de fato remetido ao arquivo terceirizado e se não está no próprio ofício; Foro Regional informa a vara distrital; NÃO se reitera a requisição antes de 10 DIAS ÚTEIS; recebidos os autos, lança-se o recebimento nos dois sistemas." },
  { id: "ncgj2-17", lei: "Normas TJSP", ref: "NSCGJ, Tomo I, arts. 189-A a 189-G",
    frente: "Pesquisa científica em processos arquivados (arts. 189-A a 189-G).",
    verso: "Permitida a pesquisa nos processos arquivados na empresa terceirizada, mediante CREDENCIAMENTO na Coordenadoria de Gestão Documental e Arquivos (SPI 2.4), com tema e lista de processos, e TERMO de compromisso, sigilo e confidencialidade. Autorizada pelo Presidente da COMISSÃO PERMANENTE DE AVALIAÇÃO DOCUMENTAL (CPAD), pelo prazo de 30, 60 ou no MÁXIMO 90 DIAS, renováveis se justificado. NÃO há taxa de desarquivamento, mas ressarcem-se custos de cópias e materiais (art. 12, Lei 12.527/2011)." },
  { id: "ncgj2-18", lei: "Normas TJSP", ref: "NSCGJ, Tomo I, arts. 1.189 a 1.191",
    frente: "Processo eletrônico: conceito, sistema e acesso (arts. 1.189 a 1.191).",
    verso: "PROCESSO ELETRÔNICO: aquele cujas peças, documentos e atos constituem um conjunto de ARQUIVOS DIGITAIS, que tramitam, são transmitidos, comunicados, armazenados e consultados por meio eletrônico (Lei 11.419/2006). ACESSO ao sistema: I no site do TJSP por pessoa credenciada com CERTIFICAÇÃO DIGITAL (ICP-Brasil Padrão A3); II pelos entes conveniados por integração de sistemas; III nos sistemas internos por magistrados, servidores, funcionários e terceiros autorizados. USO INADEQUADO que cause prejuízo às partes ou à atividade jurisdicional → BLOQUEIO do cadastro do usuário, sem prejuízo de outras cominações legais." },
  { id: "ncgj2-19", lei: "Normas TJSP", ref: "NSCGJ, Tomo I, arts. 1.192 a 1.195 · já caiu: 2018",
    frente: "Processo eletrônico: autenticidade, assinatura e documento original (arts. 1.192 a 1.195).",
    verso: "Autenticidade e integridade garantidas por certificação digital (ICP-Brasil A3). Documentos produzidos eletronicamente são assinados digitalmente pelo autor; os DIGITALIZADOS são assinados ou rubricados no momento da digitalização ou da transmissão. Fazem a MESMA PROVA que os originais as reproduções digitalizadas juntadas por órgãos da Justiça, MP, procuradorias, autoridades policiais, repartições públicas e advogados, ressalvada alegação motivada de adulteração; os ORIGINAIS são preservados pelo detentor até o fim do prazo da AÇÃO RESCISÓRIA. Art. 1.193: o uso e sigilo da CHAVE PRIVADA é de EXCLUSIVA responsabilidade do titular; NÃO se opõe alegação de uso indevido. Art. 1.194: todos os atos são assinados eletronicamente; CARTAS ROGATÓRIAS eletrônicas são assinadas eletronicamente e IMPRESSAS para carimbo e assinatura física do magistrado. Art. 1.195: é ORIGINAL a versão armazenada no servidor do TJSP, ENQUANTO o processo estiver em tramitação OU arquivado." },
  { id: "ncgj2-20", lei: "Normas TJSP", ref: "NSCGJ, Tomo I, arts. 1.196 a 1.197-B",
    frente: "Peticionamento eletrônico: formação do processo e fase policial (arts. 1.196 a 1.197-B).",
    verso: "Regra: petições produzidas eletronicamente e enviadas pelo sistema; meio físico só nos casos previstos. A correta formação é responsabilidade do ADVOGADO ou procurador, que carrega as peças na ordem: I petição; II procuração; III documentos pessoais/atos constitutivos; IV documentos de instrução; V comprovante das despesas; documentos classificados e organizados; havendo prejuízo ao contraditório, o juiz determina nova apresentação. Art. 1.197-A: compete à AUTORIDADE POLICIAL o correto cadastro e classificação do expediente; termos eletrônicos de oitivas e interrogatórios assinados digitalmente pela autoridade; os termos físicos permanecem na DELEGACIA e podem ser solicitados a qualquer tempo. Art. 1.197-B: MEDIDAS CAUTELARES criminais e infracionais tramitam com numeração PRÓPRIA e independente; VEDADO pedido cautelar por petição intermediária ou no relatório final (o juiz determina a correta distribuição); chegando o expediente principal, a cautelar é APENSADA a ele." },
  { id: "ncgj2-21", lei: "Normas TJSP", ref: "NSCGJ, Tomo I, arts. 1.198 a 1.201 · já caiu",
    frente: "Atos processuais eletrônicos: tempestividade, recibo e suspensão de prazos (arts. 1.198 a 1.201).",
    verso: "Realizados no dia e hora do RECEBIMENTO no sistema. TEMPESTIVA a petição recebida até as 24 HORAS do último dia, pelo horário de BRASÍLIA; prazo vencendo em dia sem expediente forense prorroga-se até as 24h do primeiro dia útil; petições recebidas em dia sem expediente consideram-se protocoladas no primeiro dia útil seguinte. RECIBO ELETRÔNICO com data, hora e identificação do processo. Sistema ininterruptamente disponível, salvo manutenção. A SUSPENSÃO dos prazos NÃO impede o envio de petições e a movimentação de processos; os pedidos decorrentes são apreciados após o término da suspensão, ressalvada a urgência." },
  { id: "ncgj2-22", lei: "Normas TJSP", ref: "NSCGJ, Tomo I, arts. 1.202 a 1.204",
    frente: "Indisponibilidade do sistema: o que é e como é aferida (arts. 1.202 a 1.204).",
    verso: "Caracteriza indisponibilidade (ou impossibilidade técnica do TJ) a falta de oferta ao público externo de: I consulta aos autos digitais; II transmissão eletrônica de peças (inclusive petição); III acesso a citações, intimações e notificações eletrônicas. Falhas de transmissão entre as estações do usuário e a rede pública, ou nos equipamentos/programas do usuário, NÃO caracterizam. Aferição por sistema de AUDITORIA da STI, em intervalos NÃO superiores a 5 MINUTOS; relatório público de interrupções com data, hora e minuto de início e fim, período total entre 6h00 e 23h00 e serviços afetados; reconhecida no site www.tjsp.jus.br." },
  { id: "ncgj2-23", lei: "Normas TJSP", ref: "NSCGJ, Tomo I, art. 1.205 · já caiu",
    frente: "Efeitos da indisponibilidade: prorrogação de prazos e petição em papel (art. 1.205).",
    verso: "I prorroga-se AUTOMATICAMENTE para o primeiro dia útil seguinte o prazo que vencer no dia da indisponibilidade se ela: a) for SUPERIOR a 60 MINUTOS (ininterruptos ou não), entre 6h00 e 23h00; b) ocorrer entre 23h e 24h. II permite-se petição em MEIO FÍSICO nos casos de RISCO DE PERECIMENTO DE DIREITO. NÃO produz o efeito: indisponibilidade entre 0h00 e 6h00 de dias de expediente, em feriados e fins de semana. Prazos em HORA ou MINUTO: prorrogados até 24h do dia útil seguinte se a indisponibilidade superar 60 MINUTOS nas ÚLTIMAS 24 HORAS do prazo ou ocorrer nos 60 MINUTOS anteriores ao término. Petições urgentes em papel: recebidas no horário do fórum, no dia da indisponibilidade, previamente admitidas pelo Juiz Corregedor Permanente do Distribuidor ou juiz do feito, com CÓPIAS legíveis (vedados originais)." },
  { id: "ncgj2-24", lei: "Normas TJSP", ref: "NSCGJ, Tomo I, arts. 1.205-A a 1.205-D",
    frente: "Indisponibilidade SEVERA e suspensão automática de prazos (arts. 1.205-A a 1.205-D).",
    verso: "INDISPONIBILIDADE SEVERA: indisponibilidade, lentidão ou intermitência SUPERIOR a 3 HORAS, ininterruptas ou não, entre 9h e 19h, em DIAS ÚTEIS, de qualquer serviço do art. 1.202. Por DOIS OU MAIS DIAS CONSECUTIVOS → SUSPENSÃO AUTOMÁTICA dos prazos processuais A PARTIR DO SEGUNDO DIA, nos feitos digitais e nas intimações eletrônicas de processos físicos; retomam no primeiro dia útil sem indisponibilidade severa; não prejudica audiências. Divulgada no site e publicada DIARIAMENTE no DJE (Prov. CSM 2.537/2019). NÃO alcança o período de graça de 10 DIAS para ciência dos entes que recebem intimação via Portal e-SAJ." },
  { id: "ncgj2-25", lei: "Normas TJSP", ref: "NSCGJ, Tomo I, arts. 1.206 a 1.208",
    frente: "Exceções ao peticionamento eletrônico: parte sem advogado e alimentos de balcão (arts. 1.206 a 1.208).",
    verso: "Pedidos em MEIO FÍSICO são recebidos nas hipóteses legais em que for DISPENSADA a assistência de advogado, com CÓPIAS legíveis (vedados originais). Informações de autoridades e auxiliares da justiça sem advogado: em PDF para o e-mail institucional do ofício, com o NÚMERO DO PROCESSO no ASSUNTO; o ofício classifica e vincula ao processo. ALIMENTOS DE BALCÃO (Família e Sucessões): o pedido sem advogado, recepcionado ou reduzido a termo, vai ao DISTRIBUIDOR para cadastro e digitalização; a petição física aguarda no ofício por 45 DIAS para retirada pelo autor, sob pena de INUTILIZAÇÃO (o autor é cientificado no comparecimento)." },
  { id: "ncgj2-26", lei: "Normas TJSP", ref: "NSCGJ, Tomo I, arts. 1.209 a 1.211",
    frente: "Distribuição eletrônica: portal, delegacias e cancelamento do protocolo (arts. 1.209 a 1.211).",
    verso: "Peticionamento inicial para Varas digitais ou híbridas pelo PORTAL e-SAJ. Ações da INFÂNCIA E JUVENTUDE e do JEC enviadas eletronicamente são distribuídas pelo Distribuidor; expedientes recebidos em cartório (autorização de viagem, Conselho Tutelar, cadastramento para adoção, atermação) são cadastrados pelo ofício respectivo. Expedientes criminais/infracionais das delegacias recebem numeração única da RES. CNJ 65 e distribuição AUTOMÁTICA; delegacias usam a Tabela Unificada do CNJ. Sem distribuição automática, o Serviço de Distribuição CANCELA o protocolo, registrando o motivo e intimando pelo DJE, quando: petição a varas não digitais; a juízo diverso do indicado; documentos sem petição inicial; petição intermediária enviada pelo peticionamento de iniciais. O Serviço NÃO altera competência, classe e assunto, salvo manifesta divergência (dúvidas ao Juiz Corregedor Permanente). Petições INICIAIS URGENTES: distribuição com PRIORIDADE." },
  { id: "ncgj2-27", lei: "Normas TJSP", ref: "NSCGJ, Tomo I, arts. 1.212 a 1.219",
    frente: "Distribuição: petição em papel, embargos, reconvenção e BNMP (arts. 1.212 a 1.219).",
    verso: "Petição inicial em papel só se observados os requisitos do art. 1.205, §4º; digitaliza-se e o requerente tem 45 DIAS para retirá-la, sob pena de inutilização; com sistema inoperante no Distribuidor: SORTEIO sob a presidência do Juiz Corregedor Permanente, com termo nos autos. Petição inicial em papel NÃO é recebida se indeferida a distribuição. EMBARGOS À EXECUÇÃO e de TERCEIROS, CUMPRIMENTO DE SENTENÇA e RESTAURAÇÃO DE AUTOS: peticionamento eletrônico OBRIGATÓRIO e formato digital, independentemente do meio do principal; anota-se na capa do principal físico que os embargos tramitam em formato eletrônico. RECONVENÇÃO em ação principal FÍSICA segue o peticionamento FÍSICO; o ofício comunica ao Distribuidor para anotação. Distribuição equivocada de delegacia entre Foro competente e Foro Plantão: redistribuição por ATO ORDINATÓRIO, sem decisão judicial. BNMP 2.0: duplicidade → mantém-se a numeração do expediente em que foram emitidos mandado de prisão, ordem de liberação ou alvará; cancela-se o outro, trasladando as peças." },
  { id: "ncgj2-28", lei: "Normas TJSP", ref: "NSCGJ, Tomo I, arts. 1.220 a 1.223",
    frente: "Protocolo de petições intermediárias (arts. 1.220 a 1.223).",
    verso: "Apresentadas pelo PETICIONAMENTO ELETRÔNICO e encaminhadas diretamente ao ofício de justiça. Se o processo for MATERIALIZADO, aceitam-se petições em meio físico; retomada a tramitação eletrônica, não mais. Os Setores de Protocolo NÃO podem receber petições em papel para processos eletrônicos; em caso de recebimento indevido, o Setor de Protocolo de origem CANCELA o protocolo e INTIMA pelo DJE para retirada (se o ofício verifica antes do cadastramento, devolve ao protocolo; após, regulariza). Nos Foros Digitais admite-se protocolo integrado de petições em papel para processos físicos de outras Comarcas. Indisponibilidade: petição intermediária em papel é recebida se observados os requisitos do art. 1.205, §4º; deferida a juntada, o ofício protocola (dispensada a remessa ao Protocolo) e digitaliza; o requerente tem 45 DIAS, a partir da digitalização, para retirar, sob pena de inutilização." },
  { id: "ncgj2-29", lei: "Normas TJSP", ref: "NSCGJ, Tomo I, art. 1.224",
    frente: "Consulta livre e acesso integral ao processo eletrônico (art. 1.224).",
    verso: "É LIVRE, no site do TJSP, a consulta às movimentações, ao INTEIRO TEOR de decisões, sentenças, votos, acórdãos e aos mandados de prisão registrados no BNMP. ADVOGADO, DEFENSOR, PARTES e MP cadastrados e habilitados nos autos têm acesso a TODO o conteúdo. Advogados, defensores, procuradores e MP NÃO vinculados ao processo, previamente identificados, acessam todos os atos e documentos, EXCETO em processos em SIGILO ou SEGREDO DE JUSTIÇA." },
  { id: "ncgj2-30", lei: "Normas TJSP", ref: "NSCGJ, Tomo I, art. 1.225",
    frente: "Segredo de justiça no processo eletrônico (art. 1.225).",
    verso: "Só podem ser consultados pelas PARTES e PROCURADORES habilitados. A indicação é incluída: I no AJUIZAMENTO, por indicação do advogado, procurador ou autoridade policial; II na TRANSMISSÃO de recurso de 1º grau, pelo órgão de origem; III por determinação do JUIZ ou RELATOR; IV AUTOMATICAMENTE, por previsão legal, conforme tabela de classes e assuntos. Impede a consulta por quem não seja parte; é PRESUMIDA VÁLIDA até decisão judicial em contrário (de ofício ou a requerimento); a indicação do advogado ou procurador é submetida à IMEDIATA análise do juiz." },
  { id: "ncgj2-31", lei: "Normas TJSP", ref: "NSCGJ, Tomo I, art. 1.226 · já caiu: 2018",
    frente: "Consulta à íntegra pela internet: advogados, partes, auxiliares e vítima (art. 1.226).",
    verso: "I ADVOGADOS cadastrados no Portal e-SAJ, com certificação digital ou login e senha, consultam a íntegra dos processos PÚBLICOS e dos em SEGREDO DE JUSTIÇA se vinculados por PROCURAÇÃO; II às PARTES fornece-se senha com a CITAÇÃO ou quando solicitada (o advogado pode requerer e retirar, certificando-se nos autos); III senha a TERCEIROS legitimamente interessados (autos em sigilo), PERITOS, assistentes e outros auxiliares nomeados, conforme a participação, MEDIANTE AUTORIZAÇÃO DO MAGISTRADO; IV na EXECUÇÃO CRIMINAL eletrônica, mesmo em segredo, a VÍTIMA recebe senha, quando solicitada, pelo tempo da pena (renovável). Solicitação aos canais de atendimento virtual com cópia do documento com foto; a Unidade confirma a identidade por VIDEOCONFERÊNCIA; verifica se a CITAÇÃO já foi efetivada (se não, procede ao ato); envia a senha pelo mesmo canal, juntando o histórico." },
  { id: "ncgj2-32", lei: "Normas TJSP", ref: "NSCGJ, Tomo I, arts. 1.226-A e 1.227 · já caiu: 2018",
    frente: "Terceiro interessado: senha de 24 horas e impressão de documentos (arts. 1.226-A e 1.227).",
    verso: "O acesso à íntegra de processos digitais que NÃO tramitem em segredo, a TERCEIRO INTERESSADO, é franqueado mediante SENHA PESSOAL e INTRANSFERÍVEL, utilizável por 24 HORAS após a emissão. O terceiro encaminha requerimento com qualificação e DECLARAÇÃO DE RESPONSABILIDADE pessoal pelo conteúdo, com cópia de documento com foto; identidade confirmada por VIDEOCONFERÊNCIA; histórico e declaração juntados aos autos. Pedidos PRESENCIAIS: a Unidade imprime a senha; os requerimentos digitalizados e importados são arquivados em classificador próprio e podem ser INUTILIZADOS após 45 DIAS (Comunicado SAD 11/2010). Art. 1.227: sempre que possível, os documentos são disponibilizados na internet para IMPRESSÃO pelo advogado ou interessado." },
  { id: "ncgj2-33", lei: "Normas TJSP", ref: "NSCGJ, Tomo I, arts. 1.228 a 1.232",
    frente: "Tramitação do processo eletrônico: providências gerais do ofício (arts. 1.228 a 1.232).",
    verso: "Art. 1.228: aplicam-se SUBSIDIARIAMENTE e no que compatível os demais capítulos das Normas. Art. 1.229: recebidos os autos digitais do distribuidor, o ofício IDENTIFICA os processos de tratamento URGENTE (liminar, tutela) e corrige, se o caso, o cadastro do advogado (que também pode corrigir pela funcionalidade); a mesma identificação após manifestações do MP, Defensoria, auxiliares e partes; correção de dados de expedientes da Polícia Civil na fase investigatória é comunicada à AUTORIDADE POLICIAL. Art. 1.230: o ofício confere as peças e o cadastro de advogados para publicação no DJE. Art. 1.231: os ALERTAS DE PENDÊNCIA só são excluídos logo após o efetivo encerramento da pendência. Art. 1.232: informações que devam ser anotadas na CAPA dos autos (penhora no rosto dos autos, agravos, embargos de terceiro e à execução) serão ALERTAS DE PENDÊNCIA." },
  { id: "ncgj2-34", lei: "Normas TJSP", ref: "NSCGJ, Tomo I, art. 1.233",
    frente: "Tarjas coloridas obrigatórias no processo eletrônico (art. 1.233).",
    verso: "Obrigatório o uso das tarjas para: justiça GRATUITA; RÉU PRESO; prioridade IDOSO, PESSOA COM DEFICIÊNCIA e DOENÇA GRAVE; URGENTE; SEGREDO DE JUSTIÇA; atuação do MP; SIGILO absoluto e externo; pedido de diligência; cadastro e análise de PENHORA no rosto dos autos; PRESO POR OUTRO JUÍZO; suspensão do ART. 89 da Lei 9.099/95; VÍTIMA CRIANÇA ou ADOLESCENTE; SENTENÇA REGISTRADA; DIGNIDADE SEXUAL; prioridade EXECUÇÃO FISCAL; DEFENSORIA PÚBLICA; CURADOR ESPECIAL/ADVOGADO DATIVO; processos SUSPENSOS (CPP, art. 366); réu menor de 21 ou maior de 70 anos; competência LEI MARIA DA PENHA; vítima ou testemunha PROTEGIDA; processo de ADOÇÃO; crimes dolosos contra a vida; JUÍZO 100% DIGITAL; pessoa protegida pelo PROVITA/SP. Enquanto não houver tarja, usa-se ALERTA no sistema." },
  { id: "ncgj2-35", lei: "Normas TJSP", ref: "NSCGJ, Tomo I, arts. 1.234 a 1.236",
    frente: "Botões de atividade, modelos e verificação mensal das filas (arts. 1.234 a 1.236).",
    verso: "O ofício usa OBRIGATORIAMENTE os BOTÕES DE ATIVIDADE sempre que a funcionalidade puder ser feita por eles. Quando o sistema permitir, magistrado, gabinete e ofício configuram OBRIGATORIAMENTE os atos na criação de modelos de despacho, decisão, sentença e ato ordinatório. Pelo menos UMA VEZ POR MÊS o ofício verifica todas as filas do subfluxo de processos e petições e as fases do subfluxo de documentos, movimentando os processos inseridos indevidamente; para a PRESCRIÇÃO (criminal e execução criminal) verificam-se as filas 'Previsão da Prescrição' e 'Processos Prescritos' do subfluxo 'Acompanhamento'." },
  { id: "ncgj2-36", lei: "Normas TJSP", ref: "NSCGJ, Tomo I, arts. 1.237 a 1.239",
    frente: "Elaboração de expedientes: modelos institucionais e assinatura do juiz (arts. 1.237 a 1.239).",
    verso: "Usam-se os modelos de expediente INSTITUCIONAIS padronizados, aprovados pela CORREGEDORIA GERAL, com MOVIMENTAÇÃO vinculada (estatística fidedigna). Modelos de GRUPO ou USUÁRIO: criados a partir dos institucionais ou da autoria intelectual do magistrado, só para: ajuizamentos, atos ordinatórios, autos, cartas precatórias/rogatórias, certidões, decisões, despachos, editais, expedientes do Distribuidor, formais, mandados, ofícios, requerimentos, sentenças, setor técnico (Assistente Social e Psicologia), termos e termos de audiência. Modelos de grupo permitem trabalho em lote e filtro nas filas. Cartas rogatórias: procedimento do art. 131. Art. 1.239: o juiz SOMENTE lança ASSINATURA ELETRÔNICA, mesmo que o ato deva ser praticado junto à unidade de outro Estado." },
  { id: "ncgj2-37", lei: "Normas TJSP", ref: "NSCGJ, Tomo I, arts. 1.240 a 1.244",
    frente: "Conclusão e vista, cumprimento de ordens e publicidade de expedientes (arts. 1.240 a 1.244).",
    verso: "Art. 1.240: DISPENSADOS os termos de conclusão e de vista nos autos digitais; gera-se movimentação específica no encaminhamento à fila (data da remessa ao juiz, Defensoria e MP). Art. 1.241: cessada a vinculação do juiz com a vara, eventual abertura de conclusão é comunicada por e-mail institucional do magistrado, com transferência do processo no sistema. Art. 1.242: na ausência momentânea do juiz, informa-se na tela o magistrado que assinará; ele assina mediante INICIALIZAÇÃO do sistema pelo escrivão ou assistente judiciário. Art. 1.243: cumprimento de ordens pelos SUBFLUXOS de documentos (fluxo por atos). Art. 1.244: a LIBERAÇÃO dos expedientes é OBRIGATÓRIA para visibilidade externa; quando a visibilidade puder prejudicar o ato, usa-se a movimentação com RESTRIÇÃO de publicidade e só após o cumprimento libera-se." },
  { id: "ncgj2-38", lei: "Normas TJSP", ref: "NSCGJ, Tomo I, arts. 1.245 a 1.249",
    frente: "Citações, intimações e notificações no processo eletrônico (arts. 1.245 a 1.249).",
    verso: "Art. 1.245: cartas e mandados de citação contêm SENHA de acesso à íntegra dos autos pela internet; citação, intimação e notificação pelo Correio: CARTA AR DIGITAL UNIPAGINADA; é VEDADO enviar cópia da inicial em papel (o ofício imprime, mediante recolhimento do custo, quando o caso); em processos criminais ou infracionais, o mandado de citação é instruído com cópia da DENÚNCIA ou REPRESENTAÇÃO; para unidades prisionais ou de internação, o juiz pode dispensar mandado (cumprimento direto pelo ofício, com certificação por serventuário com fé pública). Art. 1.246: intimações e notificações pelo DJE. Art. 1.247: impossível o meio eletrônico → meios ordinários. Art. 1.248: instituições com INTIMAÇÃO PESSOAL (MP e Defensoria) intimadas por PORTAL próprio. Art. 1.248-A (PORTAL): certificação de remessa automática; intimação realizada no DIA DA CONSULTA ao teor (certidão de ciência); consulta em dia não útil → primeiro dia útil seguinte; consulta em até 10 DIAS CORRIDOS do envio, sob pena de intimação automática no término do prazo, com certidão de 'NÃO LEITURA'." },
  { id: "ncgj2-39", lei: "Normas TJSP", ref: "NSCGJ, Tomo I, arts. 1.250 a 1.252",
    frente: "Termo inicial de prazos: juntada do AR, mandado e carta precatória (arts. 1.250 a 1.252).",
    verso: "Correio: data da juntada do AR = digitalização e liberação pelo ofício (AR físico) ou data da disponibilização pelos Correios (AR digital). OFICIAL DE JUSTIÇA: mandado POSITIVO é digitalizado e liberado e, em seguida, liberada a certidão assinada eletronicamente — a partir daí considera-se juntado; mandado NEGATIVO: basta liberar a certidão, sem digitalizar o mandado. CARTA PRECATÓRIA ou ROGATÓRIA: considera-se juntada quando o ofício digitaliza e libera a carta cumprida (art. 231, VI CPC); se houver a informação eletrônica do art. 232 CPC do juízo deprecado, o prazo conta da juntada dessa comunicação." },
  { id: "ncgj2-40", lei: "Normas TJSP", ref: "NSCGJ, Tomo I, arts. 1.253 a 1.255",
    frente: "Controle de prazos: fila 'aguardando decurso de prazo' (arts. 1.253 a 1.255).",
    verso: "É VEDADO controlar prazos pela fila 'aguardando decurso de prazo – publicação'. Processos que aguardam decurso de prazo da publicação no DJE vão à fila 'AGUARDANDO DECURSO DE PRAZO'; o ofício preenche a data da DISPONIBILIZAÇÃO no DJE e a quantidade de dias, e o sistema gera o termo final; verifica-se DIARIAMENTE a fila. O decurso de prazo decorrente de emissão de documentos é controlado pelo SUBFLUXO do documento (prazos indicados na configuração do ato no modelo de grupo)." },
  { id: "ncgj2-41", lei: "Normas TJSP", ref: "NSCGJ, Tomo I, arts. 1.256 a 1.257-A",
    frente: "Juntada de petições intermediárias e triagem (arts. 1.256 a 1.257-A).",
    verso: "Até a certificação automática, as petições são juntadas SEM lavrar termos, usando o tipo de petição específica que identifica a data. Na materialização, anexa-se EXTRATO ou ficha de movimentação. Petições sujeitas a distribuição: intima-se o peticionário pelo DJE a peticionar como INICIAL. Documentos recebidos por e-mail, Malote Digital etc. (se autorizados) são juntados diretamente em PDF. TRIAGEM das petições juntadas, com remessa à conclusão ou ao cumprimento: no máximo 10 DIAS CORRIDOS do protocolo; se houver pedido de TUTELA DE URGÊNCIA ou MEDIDA PROTETIVA DE URGÊNCIA: conclusão em até 48 HORAS." },
  { id: "ncgj2-42", lei: "Normas TJSP", ref: "NSCGJ, Tomo I, art. 1.258",
    frente: "Digitalização e guarda de petições e documentos em papel: prazo de 45 dias (art. 1.258).",
    verso: "Petições e documentos em papel (casos permitidos) são digitalizados, categorizados, juntados e mantidos no ofício por 45 DIAS, findos os quais, salvo ordem do juiz, são INUTILIZADOS e enviados à reciclagem: ofícios, respostas, laudos e pareceres de assistentes técnicos; documentos de processos originados no PLANTÃO judiciário; comprovantes de DEPÓSITO judicial e de MLJ cumprido; originais de AR, mandados, precatórias e rogatórias com nota de ciente; os mesmos no JEC (mesmo sem manifestação); originais de AR e cartas em que a parte não foi citada/intimada; demais documentos em Portaria do Juiz Corregedor aprovada pela CGJ. Mandados com recusa da nota de ciente sem assinatura são inutilizados pelos oficiais após a certidão. Originais de AR/mandados com nota de ciente SEM manifestação ficam em pastas individuais até o fim do prazo da AÇÃO RESCISÓRIA. A digitalização é supervisionada pelo ESCRIVÃO; ilegível → mantido em pasta e certificado ao juiz. BOLETIM DE OCORRÊNCIA circunstanciado sem inquérito é devolvido à Delegacia." },
  { id: "ncgj2-43", lei: "Normas TJSP", ref: "NSCGJ, Tomo I, arts. 1.259 e 1.260",
    frente: "Documentos de digitalização inviável e títulos executivos (arts. 1.259 e 1.260).",
    verso: "Documentos que não possam ser digitalizados em PDF (grande volume, ilegibilidade, mídias, mapas, plantas, radiografias ou que devam ser entregues no original) são apresentados ao ofício em 10 DIAS do envio da petição eletrônica que comunica o fato; devolvidos após o TRÂNSITO EM JULGADO ou quando determinado; identificados com número, partes e vara, em pastas individuais; o ofício certifica a apresentação; além da mídia original, tantas CÓPIAS quantas as partes. Cópia digital de TÍTULO EXECUTIVO extrajudicial: o juiz pode determinar o DEPÓSITO no ofício; pode determinar exibição do original só para anotações de vinculação ao processo digital, devolvendo em seguida." },
  { id: "ncgj2-44", lei: "Normas TJSP", ref: "NSCGJ, Tomo I, arts. 1.261 e 1.262",
    frente: "Peritos e auxiliares: intimação da nomeação e entrega de laudos (arts. 1.261 e 1.262).",
    verso: "Intimados da nomeação por E-MAIL do cadastro, com a SENHA de acesso aos autos digitais; aceitação ou escusa formalizadas por RESPOSTA ao e-mail institucional do ofício (digitalizada e liberada nos autos). Laudos e manifestações em PDF, por PETICIONAMENTO ELETRÔNICO direto no Portal e-SAJ com certificado digital; o perito classifica e vincula o PDF; o ofício pode corrigir a organização; sem prejuízo de outros meios (portais próprios)." },
  { id: "ncgj2-45", lei: "Normas TJSP", ref: "NSCGJ, Tomo I, arts. 1.263 a 1.265",
    frente: "Infojud, Bacenjud, Renajud e mandados de levantamento (arts. 1.263 a 1.265).",
    verso: "Informações de endereço ou situação econômico-financeira obtidas por INFOJUD ou similar são juntadas aos autos; as de natureza SIGILOSA em processos digitais com o TIPO específico de documento digital SIGILOSO (acesso restrito, via e-SAJ, aos advogados das partes e, se habilitados, defensores, promotores e instituições conveniadas); sem tipo específico: 'documento sigiloso'. BACENJUD (só bloqueio ou não) e RENAJUD (só veículos): importadas ou digitalizadas, liberadas nos autos e praticado o ato ordinatório. Art. 1.265: processos na fase de expedição de MANDADOS DE LEVANTAMENTO vão para a fila 'AG. ANÁLISE DE CARTÓRIO URGENTE'." },
  { id: "ncgj2-46", lei: "Normas TJSP", ref: "NSCGJ, Tomo I, arts. 1.266 a 1.271",
    frente: "Fac-símile e audiências no processo eletrônico (arts. 1.266 a 1.271).",
    verso: "Art. 1.266: as normas sobre FAC-SÍMILE (fax) NÃO se aplicam aos processos eletrônicos. Art. 1.267: audiências cadastradas na PAUTA do sistema, com resultado, redesignações e cancelamentos atualizados; agendamentos anotados imediatamente. Art. 1.268: a CONTESTAÇÃO e documentos para a audiência são apresentados por PETICIONAMENTO ELETRÔNICO PRÉVIO se o advogado não dispuser de meios tecnológicos na audiência; a critério do juiz, pen drive em PDF ou papel. Art. 1.269: termos de audiência ASSINADOS ELETRONICAMENTE pelo juiz; cópias IMPRESSAS e assinadas fisicamente pelos presentes e entregues aos advogados; CONTRADIÇÕES na transcrição são suscitadas ORALMENTE no momento do ato, sob pena de PRECLUSÃO. Art. 1.270: depoimento de testemunha registrado em meio audiovisual (arts. 150 e ss.) ou em termo assinado eletronicamente. Art. 1.271: a transcrição da fita de ESTENOTIPIA é feita, sempre que possível, diretamente no sistema e assinada eletronicamente." },
  { id: "ncgj2-47", lei: "Normas TJSP", ref: "NSCGJ, Tomo I, arts. 1.273 a 1.274",
    frente: "Formal de partilha, cartas de sentença e decisões terminativas em notificações (arts. 1.273 a 1.274).",
    verso: "Peças do formal de partilha, carta de adjudicação e de arrematação extraídas do processo eletrônico são IMPRESSAS pelo ofício após o pagamento da TAXA de reprodução (Lei 11.608/2003); o escrivão RUBRICA todas as folhas imediatamente, dispensada autenticação. A requerimento, podem ser expedidos para REMESSA ELETRÔNICA aos Serviços Notariais e de Registro: termos de abertura e encerramento (com folha inicial e final e SENHA de acesso ao Oficial/Tabelião), assinados eletronicamente por ESCRIVÃO e MAGISTRADO, liberados na pasta digital, com intimação da parte para a remessa. Decisões terminativas em NOTIFICAÇÕES, INTERPELAÇÕES e PROTESTOS: constará determinação de impressão a partir de consulta na internet; após o trânsito, o processo vai para a pasta de arquivados." },
  { id: "ncgj2-48", lei: "Normas TJSP", ref: "NSCGJ, Tomo I, arts. 1.275 e 1.276",
    frente: "Recursos: remessa à 2ª instância e porte de remessa e retorno (arts. 1.275 e 1.276).",
    verso: "Interposto o recurso, a remessa dos autos digitais ocorre eletronicamente pelo BOTÃO DE ATIVIDADE, SEM PENDÊNCIAS (juntada de petições, expedientes por assinar, certificação de publicações, custas e preparo, cadastro de advogados). NÃO há cobrança de PORTE DE REMESSA E RETORNO em transmissão integralmente eletrônica; havendo mídias ou objetos pela via tradicional (MALOTE), cobra-se o porte de UM VOLUME por objeto, e a certidão de remessa indica obrigatoriamente o envio ou a inexistência de mídia. Recursos aos COLÉGIOS RECURSAIS não digitalizados: o JEC imprime e autua, anexa o extrato de movimentações. Devolvidos autos materializados da 2ª instância: o ofício digitaliza as peças produzidas, categoriza e insere no processo; a tramitação retoma a forma eletrônica, com intimação das partes pelo DJE e peticionamento eletrônico obrigatório; peças materializadas e importadas assinadas digitalmente podem ser descartadas; as digitalizadas ficam arquivadas em pastas por número do processo." },
  { id: "ncgj2-49", lei: "Normas TJSP", ref: "NSCGJ, Tomo I, arts. 1.277 e 1.278",
    frente: "Agravos de instrumento, conflitos de competência e feitos dependentes (arts. 1.277 e 1.278).",
    verso: "Ao receber comunicação de julgamento de AGRAVO DE INSTRUMENTO ou CONFLITO DE COMPETÊNCIA digitais, o ofício consulta o inteiro teor com a SENHA enviada pelo Serviço de Processamento das Câmaras e junta a MENSAGEM, a CÓPIA do acórdão ou decisão monocrática e a CERTIDÃO de trânsito, sendo desnecessária a juntada das demais peças dos arts. 208 e 209; pode solicitar a senha por e-mail, mesmo antes do julgamento. Ações eletrônicas distribuídas por dependência a processos em PAPEL permanecem no formato ELETRÔNICO; anota-se na CAPA do físico a existência do feito dependente eletrônico, certificando-se em ambos o número e a forma de tramitação." },
  { id: "ncgj2-50", lei: "Normas TJSP", ref: "NSCGJ, Tomo I, arts. 1.279 a 1.284",
    frente: "Redistribuição, desentranhamento, cópias pagas e arquivamento no processo eletrônico (arts. 1.279 a 1.284).",
    verso: "REDISTRIBUIÇÃO a outras unidades de 1ª instância: ao distribuidor em FILA PRÓPRIA; se o Foro destinatário é EXCLUSIVAMENTE eletrônico, o distribuidor digitaliza os físicos; se HÍBRIDO, continuam físicos. Para outros TRIBUNAIS: o distribuidor recebe o processo materializado e impresso (ou envia mídia eletrônica quando o destino é digital). Art. 1.281: desentranhamento em autos digitais usa a funcionalidade 'TORNAR SEM EFEITO'. Art. 1.282: pedido de impressão no balcão → certidão (art. 158) e recolhimento do custo da cópia. Art. 1.283: determinado o arquivamento, o ofício verifica pendências, encerra atos do sistema, lança a movimentação e envia para fila própria, regularizando previamente movimentações e cadastros. Art. 1.284: no desarquivamento, observa-se o motivo — 'Desarquivamento SEM Reabertura' ou 'COM Reabertura' (que reativa o processo para andamento e certidões)." },
  { id: "ncgj2-51", lei: "Normas TJSP", ref: "NSCGJ, Tomo I, arts. 1.285 a 1.289",
    frente: "Cumprimento de sentença no processo eletrônico (arts. 1.285 a 1.289).",
    verso: "Sentença proferida em processo FÍSICO: o cumprimento tramita em meio ELETRÔNICO nas unidades híbridas; após o trânsito, despacho ou ato ordinatório cientifica as partes. Requerimento por PETICIONAMENTO ELETRÔNICO instruído com: sentença e acórdão; certidão de trânsito; demonstrativo do débito atualizado (quantia certa); mandado de citação cumprido e procurações. Cadastrado como INCIDENTE autônomo com numeração PRÓPRIA. Autos físicos ficam no ofício 30 DIAS para consulta e cópias, depois baixados e arquivados; não requerida a execução em 30 DIAS, o juiz manda arquivar (desarquivamento a pedido). Vedada a conversão ao digital dos cumprimentos que já tramitam fisicamente sem autorização da CGJ. Contra a FAZENDA com execução anterior do mesmo processo: novos cumprimentos podem ser físicos. Aplica-se a provisórios e definitivos. Cumprimento provisório de decisão interlocutória: no mesmo formato do processo. Distribuído pelo peticionamento inicial indevidamente → cancelado pelo Distribuidor por ordem do juiz e intima-se o peticionário a peticionar como intermediário." },
  { id: "ncgj2-52", lei: "Normas TJSP", ref: "NSCGJ, Tomo I, arts. 1.290 a 1.294",
    frente: "Precatórios e RPVs: processamento do ofício requisitório (arts. 1.290 a 1.294).",
    verso: "A tramitação do requisitório ocorre EXCLUSIVAMENTE nos INCIDENTES individualizados de precatório e de RPV; os pedidos são apreciados neles, VEDADO processar no processo de conhecimento ou no cumprimento. Pago o requisitório, a extinção se faz no incidente, preferencialmente com UM MANDADO DE LEVANTAMENTO por incidente; após a sentença de extinção e ofício à DEPRE, baixa definitiva. É VEDADA a vinculação de incidentes ao processo principal (só ao cumprimento de sentença). CUMPRIMENTO DE SENTENÇA AUTÔNOMO permitido: requisitório incontroverso já expedido e remanescente controverso transitado; diferenças de outras revisões de precatório; credor não liquidado antes do requisitório informado à DEPRE; compete ao juízo da fase de conhecimento. Art. 1.293: VEDADO precatório COMPLEMENTAR, salvo as hipóteses da Res. CNJ 303 (novo incidente, só pelo Portal e-SAJ). Art. 1.294: no JEFP, para partes sem advogado/defensor, o incidente é cadastrado pela UNIDADE JUDICIAL." },
  { id: "ncgj2-53", lei: "Normas TJSP", ref: "NSCGJ, Tomo I, arts. 1.295 a 1.299",
    frente: "Precatórios na Capital: UPEFAZ e Varas da Fazenda (arts. 1.295 a 1.299).",
    verso: "O juiz zela para que cumprimentos e incidentes sejam instruídos com a PROCURAÇÃO do advogado que instaurou a execução. As Varas da Fazenda do Foro Central enviam cumprimento e precatório à UPEFAZ SOMENTE após a confirmação do NÚMERO DE ORDEM indicado pela DEPRE; antes, analisam as questões pendentes (habilitação de herdeiros, cessão de crédito, penhora no rosto, impugnações, prioridade especial, levantamento) — VEDADA a mera 'anotação' do pedido; remessa com pendências → NÃO recebimento pela UPEFAZ. Precatório e RPV concomitantes: autos vão à UPEFAZ após pagamento, levantamento e extinção da OPV. Processos físicos ARQUIVADOS não vão à UPEFAZ; reativa-se 'apenas no sistema' (movimentação 'Reativação do Processo', informando que permanece arquivado, pacote e vara de origem)." },
  { id: "ncgj2-54", lei: "Normas TJSP", ref: "NSCGJ, Tomo I, arts. 1.300 e 1.301",
    frente: "Comunicações obrigatórias à DEPRE (arts. 1.300 e 1.301).",
    verso: "O juízo da execução comunica ELETRONICAMENTE à DEPRE, com modelos institucionais: I CESSÃO de crédito; II SUCESSÃO processual (falecimento, divórcio, dissolução de união); III deferimento de PENHORA de valores de precatório (SÓ pela funcionalidade própria de registro da penhora no incidente, que insere a tarja — vedada outra comunicação); IV preferência a portadores de DOENÇA GRAVE ou PESSOA COM DEFICIÊNCIA; V acolhimento de impugnação ou revisão de cálculo (critério de cálculo judicial); VI outras informações relevantes, em especial alteração do BENEFICIÁRIO. Art. 1.301: expedientes de processos físicos ou digitais sem incidente individualizado também seguem eletronicamente à DEPRE." }
]);
